// ============================================================================
// PTP_apb: APB4 register wrapper around PTP_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/PTP.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/PTP.md
// ============================================================================
module PTP_apb #(
  parameter int FIFO_DEPTH = 4
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  output logic [47:0] t_sec,
  output logic [29:0] t_ns,
  output logic pps,
  output logic target_hit,
  input logic ext_evt,
  input logic rx_dv,
  input logic rx_er,
  input logic [7:0] rxd,
  input logic tx_en,
  input logic tx_er,
  input logic [7:0] txd
);
  localparam logic [31:0] ID_VALUE = 32'h50540100;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [32:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd33) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic [7:0]    c_cfg_inc_ns;
  logic [31:0]   c_cfg_inc_frac;
  logic          c_time_set;
  logic [47:0]   c_set_sec;
  logic [29:0]   c_set_ns;
  logic          c_time_step;
  logic [31:0]   c_step_ns;
  logic          c_snap;
  logic [47:0]   c_snap_sec;
  logic [29:0]   c_snap_ns;
  logic          c_pps_en;
  logic [29:0]   c_pps_width_ns;
  logic          c_sec_tick;
  logic          c_target_arm;
  logic          c_target_disarm;
  logic [47:0]   c_target_sec;
  logic [29:0]   c_target_ns;
  logic          c_target_armed;
  logic          c_target_hit;
  logic          c_evt_valid;
  logic [47:0]   c_evt_sec;
  logic [29:0]   c_evt_ns;
  logic [15:0]   c_cfg_rx_lat_ns;
  logic [15:0]   c_cfg_tx_lat_ns;
  logic          c_cfg_l2_en;
  logic          c_cfg_ipv4_en;
  logic          c_cfg_ipv6_en;
  logic          c_rxq_valid;
  logic          c_rxq_pop;
  logic [3:0]    c_rxq_type;
  logic [7:0]    c_rxq_domain;
  logic [15:0]   c_rxq_seq;
  logic [47:0]   c_rxq_sec;
  logic [29:0]   c_rxq_ns;
  logic          c_rxq_ovf;
  logic          c_txq_valid;
  logic          c_txq_pop;
  logic [3:0]    c_txq_type;
  logic [7:0]    c_txq_domain;
  logic [15:0]   c_txq_seq;
  logic [47:0]   c_txq_sec;
  logic [29:0]   c_txq_ns;
  logic          c_txq_ovf;
  PTP_top #(.FIFO_DEPTH(FIFO_DEPTH)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .cfg_inc_ns(c_cfg_inc_ns),
    .cfg_inc_frac(c_cfg_inc_frac),
    .time_set(c_time_set),
    .set_sec(c_set_sec),
    .set_ns(c_set_ns),
    .time_step(c_time_step),
    .step_ns(c_step_ns),
    .snap(c_snap),
    .t_sec(t_sec),
    .t_ns(t_ns),
    .snap_sec(c_snap_sec),
    .snap_ns(c_snap_ns),
    .pps_en(c_pps_en),
    .pps_width_ns(c_pps_width_ns),
    .pps(pps),
    .sec_tick(c_sec_tick),
    .target_arm(c_target_arm),
    .target_disarm(c_target_disarm),
    .target_sec(c_target_sec),
    .target_ns(c_target_ns),
    .target_armed(c_target_armed),
    .target_hit(c_target_hit),
    .ext_evt(ext_evt),
    .evt_valid(c_evt_valid),
    .evt_sec(c_evt_sec),
    .evt_ns(c_evt_ns),
    .rx_dv(rx_dv),
    .rx_er(rx_er),
    .rxd(rxd),
    .tx_en(tx_en),
    .tx_er(tx_er),
    .txd(txd),
    .cfg_rx_lat_ns(c_cfg_rx_lat_ns),
    .cfg_tx_lat_ns(c_cfg_tx_lat_ns),
    .cfg_l2_en(c_cfg_l2_en),
    .cfg_ipv4_en(c_cfg_ipv4_en),
    .cfg_ipv6_en(c_cfg_ipv6_en),
    .rxq_valid(c_rxq_valid),
    .rxq_pop(c_rxq_pop),
    .rxq_type(c_rxq_type),
    .rxq_domain(c_rxq_domain),
    .rxq_seq(c_rxq_seq),
    .rxq_sec(c_rxq_sec),
    .rxq_ns(c_rxq_ns),
    .rxq_ovf(c_rxq_ovf),
    .txq_valid(c_txq_valid),
    .txq_pop(c_txq_pop),
    .txq_type(c_txq_type),
    .txq_domain(c_txq_domain),
    .txq_seq(c_txq_seq),
    .txq_sec(c_txq_sec),
    .txq_ns(c_txq_ns),
    .txq_ovf(c_txq_ovf)
  );
  assign target_hit = c_target_hit;  // also readable in the registers

  // ---------------- registers ----------------
  logic [6:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [7:0] r_INC;   // 12'h014 INC
  logic [31:0] r_INC_FRAC;   // 12'h018 INC_FRAC
  logic [31:0] r_SET0;   // 12'h01C SET0
  logic [15:0] r_SET1;   // 12'h020 SET1
  logic [29:0] r_SET2;   // 12'h024 SET2
  logic [31:0] r_STEP;   // 12'h028 STEP
  logic [4:0] p_CMD;   // 12'h02C CMD (pulses)
  logic [30:0] r_PPS;   // 12'h03C PPS
  logic [31:0] r_TARGET0;   // 12'h040 TARGET0
  logic [15:0] r_TARGET1;   // 12'h044 TARGET1
  logic [29:0] r_TARGET2;   // 12'h048 TARGET2
  logic [2:0] r_TSU_CFG;   // 12'h058 TSU_CFG
  logic [31:0] r_LAT;   // 12'h05C LAT
  logic [27:0] h_RXTS0;   // 12'h064 RXTS0 holding register
  logic [31:0] h_RXTS1;   // 12'h068 RXTS1 holding register
  logic [15:0] h_RXTS2;   // 12'h06C RXTS2 holding register
  logic [29:0] h_RXTS3;   // 12'h070 RXTS3 holding register
  logic [27:0] h_TXTS0;   // 12'h074 TXTS0 holding register
  logic [31:0] h_TXTS1;   // 12'h078 TXTS1 holding register
  logic [15:0] h_TXTS2;   // 12'h07C TXTS2 holding register
  logic [29:0] h_TXTS3;   // 12'h080 TXTS3 holding register
  logic avail_RXTS;
  logic avail_TXTS;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_INC <= 8'h8;
      r_INC_FRAC <= 32'h0;
      r_SET0 <= 32'h0;
      r_SET1 <= 16'h0;
      r_SET2 <= 30'h0;
      r_STEP <= 32'h0;
      p_CMD <= '0;
      r_PPS <= 31'h0;
      r_TARGET0 <= 32'h0;
      r_TARGET1 <= 16'h0;
      r_TARGET2 <= 30'h0;
      r_TSU_CFG <= 3'h7;
      r_LAT <= 32'h0;
      h_RXTS0 <= '0;
      h_RXTS1 <= '0;
      h_RXTS2 <= '0;
      h_RXTS3 <= '0;
      h_TXTS0 <= '0;
      h_TXTS1 <= '0;
      h_TXTS2 <= '0;
      h_TXTS3 <= '0;
      avail_RXTS <= 1'b0;
      avail_TXTS <= 1'b0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[6:0] & wmask[6:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[6:0]) | (PWDATA[6:0] & wmask[6:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_INC <= (r_INC & ~wmask[7:0]) | (PWDATA[7:0] & wmask[7:0]);
      if (wr && hit[6]) r_INC_FRAC <= (r_INC_FRAC & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[7]) r_SET0 <= (r_SET0 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[8]) r_SET1 <= (r_SET1 & ~wmask[15:0]) | (PWDATA[15:0] & wmask[15:0]);
      if (wr && hit[9]) r_SET2 <= (r_SET2 & ~wmask[29:0]) | (PWDATA[29:0] & wmask[29:0]);
      if (wr && hit[10]) r_STEP <= (r_STEP & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      p_CMD <= (wr && hit[11]) ? PWDATA[4:0] & wmask[4:0] : '0;
      if (wr && hit[15]) r_PPS <= (r_PPS & ~wmask[30:0]) | (PWDATA[30:0] & wmask[30:0]);
      if (wr && hit[16]) r_TARGET0 <= (r_TARGET0 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[17]) r_TARGET1 <= (r_TARGET1 & ~wmask[15:0]) | (PWDATA[15:0] & wmask[15:0]);
      if (wr && hit[18]) r_TARGET2 <= (r_TARGET2 & ~wmask[29:0]) | (PWDATA[29:0] & wmask[29:0]);
      if (wr && hit[22]) r_TSU_CFG <= (r_TSU_CFG & ~wmask[2:0]) | (PWDATA[2:0] & wmask[2:0]);
      if (wr && hit[23]) r_LAT <= (r_LAT & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (c_rxq_valid && (!avail_RXTS || (rd && hit[28]))) begin
        h_RXTS0[3:0] <= c_rxq_type[3:0];
        h_RXTS0[11:4] <= c_rxq_domain[7:0];
        h_RXTS0[27:12] <= c_rxq_seq[15:0];
        h_RXTS1[31:0] <= c_rxq_sec[31:0];
        h_RXTS2[15:0] <= c_rxq_sec[47:32];
        h_RXTS3[29:0] <= c_rxq_ns[29:0];
        avail_RXTS <= 1'b1;
      end else if (rd && hit[28]) avail_RXTS <= 1'b0;
      if (c_txq_valid && (!avail_TXTS || (rd && hit[32]))) begin
        h_TXTS0[3:0] <= c_txq_type[3:0];
        h_TXTS0[11:4] <= c_txq_domain[7:0];
        h_TXTS0[27:12] <= c_txq_seq[15:0];
        h_TXTS1[31:0] <= c_txq_sec[31:0];
        h_TXTS2[15:0] <= c_txq_sec[47:32];
        h_TXTS3[29:0] <= c_txq_ns[29:0];
        avail_TXTS <= 1'b1;
      end else if (rd && hit[32]) avail_TXTS <= 1'b0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_cfg_inc_ns = r_INC[7:0];
  assign c_cfg_inc_frac = r_INC_FRAC[31:0];
  assign c_set_sec[31:0] = r_SET0[31:0];
  assign c_set_sec[47:32] = r_SET1[15:0];
  assign c_set_ns = r_SET2[29:0];
  assign c_step_ns = r_STEP[31:0];
  assign c_time_set = p_CMD[0:0];
  assign c_time_step = p_CMD[1:1];
  assign c_snap = p_CMD[2:2];
  assign c_target_arm = p_CMD[3:3];
  assign c_target_disarm = p_CMD[4:4];
  assign c_pps_en = r_PPS[0:0];
  assign c_pps_width_ns = r_PPS[30:1];
  assign c_target_sec[31:0] = r_TARGET0[31:0];
  assign c_target_sec[47:32] = r_TARGET1[15:0];
  assign c_target_ns = r_TARGET2[29:0];
  assign c_cfg_l2_en = r_TSU_CFG[0:0];
  assign c_cfg_ipv4_en = r_TSU_CFG[1:1];
  assign c_cfg_ipv6_en = r_TSU_CFG[2:2];
  assign c_cfg_rx_lat_ns = r_LAT[15:0];
  assign c_cfg_tx_lat_ns = r_LAT[31:16];
  assign c_rxq_pop = ~avail_RXTS | (rd & hit[28]);
  assign c_txq_pop = ~avail_TXTS | (rd & hit[32]);

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_sec_tick;
    irq_set[1] = c_target_hit;
    irq_set[2] = c_evt_valid;
    irq_set[3] = c_rxq_ovf;
    irq_set[4] = c_txq_ovf;
    irq_set[5] = c_rxq_valid & (~avail_RXTS | (rd & hit[28]));
    irq_set[6] = c_txq_valid & (~avail_TXTS | (rd & hit[32]));
  end
  assign irq = |(irq_status & irq_enable);
  wire [1:0] flags = {avail_TXTS, avail_RXTS};

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd3: apb_rdata = 32'(flags);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_INC);
      10'd6: apb_rdata = 32'(r_INC_FRAC);
      10'd7: apb_rdata = 32'(r_SET0);
      10'd8: apb_rdata = 32'(r_SET1);
      10'd9: apb_rdata = 32'(r_SET2);
      10'd10: apb_rdata = 32'(r_STEP);
      10'd12: apb_rdata = 32'({c_snap_sec[31:0]});
      10'd13: apb_rdata = 32'({c_snap_sec[47:32]});
      10'd14: apb_rdata = 32'({c_snap_ns});
      10'd15: apb_rdata = 32'(r_PPS);
      10'd16: apb_rdata = 32'(r_TARGET0);
      10'd17: apb_rdata = 32'(r_TARGET1);
      10'd18: apb_rdata = 32'(r_TARGET2);
      10'd19: apb_rdata = 32'({c_evt_sec[31:0]});
      10'd20: apb_rdata = 32'({c_evt_sec[47:32]});
      10'd21: apb_rdata = 32'({c_evt_ns});
      10'd22: apb_rdata = 32'(r_TSU_CFG);
      10'd23: apb_rdata = 32'(r_LAT);
      10'd24: apb_rdata = 32'({c_target_armed});
      10'd25: apb_rdata = 32'(h_RXTS0);
      10'd26: apb_rdata = 32'(h_RXTS1);
      10'd27: apb_rdata = 32'(h_RXTS2);
      10'd28: apb_rdata = 32'(h_RXTS3);
      10'd29: apb_rdata = 32'(h_TXTS0);
      10'd30: apb_rdata = 32'(h_TXTS1);
      10'd31: apb_rdata = 32'(h_TXTS2);
      10'd32: apb_rdata = 32'(h_TXTS3);
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
